data:
{
 "_comment": "The triage taxonomy. The triage skill, the block validator and the triage playbook all read this List: a type is valid for an issue only when its domain (detection or posture, decided by the issue route) is in `domains`; anything else goes to `other`. `sub_playbook` is the playbook the type branches to, `skill` the skill its investigation session loads (a {domain: skill} map where the skill depends on the domain). Changing a name or adding a type needs a matching sub-playbook and a playbook condition branch; a content test checks the skill text and this List agree.",
 "severities": [
  "low",
  "medium",
  "high",
  "critical"
 ],
 "types": [
  {
   "name": "identity_threat",
   "description": "Sign-in anomaly, credential use or session abuse by a person or service identity.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriageIdentityThreat",
   "skill": "cortex_detection_investigation"
  },
  {
   "name": "cloud_change",
   "description": "A person or identity changed cloud network, IAM or storage configuration.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriageCloudChange",
   "skill": "cortex_detection_investigation"
  },
  {
   "name": "endpoint_threat",
   "description": "Malware, suspicious execution or persistence on a host.",
   "domains": [
    "detection"
   ],
   "sub_playbook": "GuardianTriageEndpointThreat",
   "skill": "cortex_detection_investigation"
  },
  {
   "name": "data_exposure",
   "description": "Public or over-shared data, unusual data access or exfiltration.",
   "domains": [
    "detection",
    "posture"
   ],
   "sub_playbook": "GuardianTriageDataExposure",
   "skill": {
    "detection": "cortex_detection_investigation",
    "posture": "cortex_posture_misconfiguration"
   }
  },
  {
   "name": "misconfiguration",
   "description": "A cloud (CSPM) or Kubernetes policy finding: a setting that is wrong.",
   "domains": [
    "posture"
   ],
   "sub_playbook": "GuardianTriageMisconfiguration",
   "skill": "cortex_posture_misconfiguration"
  },
  {
   "name": "vulnerability",
   "description": "A known CVE on a host, image or package.",
   "domains": [
    "posture"
   ],
   "sub_playbook": "GuardianTriageVulnerability",
   "skill": "cortex_vulnerability_triage"
  },
  {
   "name": "code_risk",
   "description": "Infrastructure-as-code, secrets or package operational risk found in code.",
   "domains": [
    "posture"
   ],
   "sub_playbook": "GuardianTriageCodeRisk",
   "skill": "cortex_vulnerability_triage"
  },
  {
   "name": "excessive_privilege",
   "description": "CIEM finding: admin or unused permissions on an identity or role.",
   "domains": [
    "posture"
   ],
   "sub_playbook": "GuardianTriageExcessivePrivilege",
   "skill": "cortex_identity_risk"
  },
  {
   "name": "attack_path",
   "description": "A graph attack path from an entry point to a sensitive asset.",
   "domains": [
    "posture"
   ],
   "sub_playbook": "GuardianTriageAttackPath",
   "skill": "cortex_attack_path"
  },
  {
   "name": "other",
   "description": "None of the above fits; an analyst decides.",
   "domains": [
    "detection",
    "posture"
   ],
   "sub_playbook": "GuardianTriageOther",
   "skill": ""
  }
 ]
}
